from search import insert_position_desc

def test_insert_desc_last():
    assert insert_position_desc([9, 7, 5, 3], 2) == 4

def test_insert_desc_first():
    assert insert_position_desc([9, 7, 5], 10) == 0

def test_desc_empty():
